import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import AnimatedPopup from '../components/AnimatedPopup';
import './AdminPanel.css';

const AdminPanel = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [pets, setPets] = useState([]);
  const [pendingTransactions, setPendingTransactions] = useState([]);
  const [transactionsLoading, setTransactionsLoading] = useState(false);
  const [transactionError, setTransactionError] = useState('');
  const [botSettings, setBotSettings] = useState({ botUser: '', redirectLink: '' });
  const [newPet, setNewPet] = useState({ name: '', rarity: 'common', value: 0, imageUrl: '' });
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [userPets, setUserPets] = useState([]);
  const [allUsers, setAllUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [recentActivity, setRecentActivity] = useState([]);
  const [showPopup, setShowPopup] = useState(false);
  const [popupMessage, setPopupMessage] = useState('');
  const [popupType, setPopupType] = useState('info');

  // Utility function to add delay between requests
  const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  // Utility function to retry failed requests
  const retryRequest = async (requestFn, retries = 3, delayMs = 1000) => {
    for (let i = 0; i < retries; i++) {
      try {
        const response = await requestFn();
        if (response.status === 429) {
          // Rate limited - wait and retry
          await delay(delayMs * (i + 1)); // Exponential backoff
          continue;
        }
        return response;
      } catch (error) {
        if (i === retries - 1) throw error; // If last attempt, throw the error
        await delay(delayMs * (i + 1)); // Wait before retrying
      }
    }
  };

  const showCustomPopup = (message, type = 'info') => {
    setPopupMessage(message);
    setPopupType(type);
    setShowPopup(true);

    // Auto-hide after 3 seconds
    setTimeout(() => {
      setShowPopup(false);
    }, 3000);
  };

  const closePopup = () => {
    setShowPopup(false);
  };

  // Load data when component mounts
  useEffect(() => {
    const loadData = async () => {
      try {
        // Fetch all users from real API
        try {
          const usersResponse = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/users`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`,
              'Content-Type': 'application/json'
            }
          }));

          if (usersResponse.ok) {
            const usersData = await usersResponse.json();
            setAllUsers(usersData.users || []);
            setUsers(usersData.users || []);
          } else {
            throw new Error(`Failed to fetch users: ${usersResponse.status}`);
          }
        } catch (err) {
          console.error('Error fetching users:', err);
          showCustomPopup(`Failed to load users: ${err.message}`, 'error');
        }

        // Add delay before fetching pets to avoid rate limiting
        await delay(200);

        // Fetch all pets from real API
        try {
          const petsResponse = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/items`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`,
              'Content-Type': 'application/json'
            }
          }));

          if (petsResponse.ok) {
            const petsData = await petsResponse.json();
            setPets(petsData);
          } else {
            throw new Error(`Failed to fetch pets: ${petsResponse.status}`);
          }
        } catch (err) {
          console.error('Error fetching pets:', err);
          showCustomPopup(`Failed to load pets: ${err.message}`, 'error');
        }

        // Add delay before fetching transactions
        await delay(200);

        // Fetch pending transactions from real API
        try {
          const transactionsResponse = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/transactions/pending`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`,
              'Content-Type': 'application/json'
            }
          }));

          if (transactionsResponse.ok) {
            const transactionsData = await transactionsResponse.json();
            setPendingTransactions(transactionsData.transactions || []);
          } else if (transactionsResponse.status === 404) {
            // Handle 404 specifically - route doesn't exist
            console.error('Pending transactions endpoint not found (404)');
            showCustomPopup('Pending transactions endpoint not found. Please check server configuration.', 'error');
          } else if (transactionsResponse.status === 403) {
            // Handle forbidden access
            console.error('Admin access denied for pending transactions');
            showCustomPopup('Access denied for pending transactions. Check admin privileges.', 'error');
          } else {
            throw new Error(`Failed to fetch transactions: ${transactionsResponse.status}`);
          }
        } catch (err) {
          console.error('Error fetching transactions:', err);
          showCustomPopup(`Failed to load transactions: ${err.message}`, 'error');
        } finally {
          setTransactionsLoading(false);
        }

        // Add delay before fetching settings
        await delay(200);

        // Fetch bot settings from real API
        try {
          const settingsResponse = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/settings`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`,
              'Content-Type': 'application/json'
            }
          }));

          if (settingsResponse.ok) {
            const settingsData = await settingsResponse.json();
            setBotSettings(settingsData.settings || { botUser: '', redirectLink: '' });
          } else {
            throw new Error(`Failed to fetch settings: ${settingsResponse.status}`);
          }
        } catch (err) {
          console.error('Error fetching settings:', err);
          // Use fallback values instead of showing error popup
          setBotSettings({ botUser: '', redirectLink: '' });
          // Only show error if it's not a 404 (which might mean the endpoint doesn't exist yet)
          if (err.message.includes('404')) {
            console.warn('Settings endpoint not found, using default settings');
          } else {
            showCustomPopup(`Failed to load settings: ${err.message}`, 'error');
          }
        }

        // Add delay before fetching recent activity
        await delay(200);

        // Fetch recent activity from real API
        try {
          const activityResponse = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/logs`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`,
              'Content-Type': 'application/json'
            }
          }));

          if (activityResponse.ok) {
            const activityData = await activityResponse.json();
            setRecentActivity(activityData.slice(0, 10) || []);
          } else {
            throw new Error(`Failed to fetch activity: ${activityResponse.status}`);
          }
        } catch (err) {
          console.error('Error fetching activity:', err);
          // Use mock data as fallback
          setRecentActivity([
            { type: 'System Started', user: 'Server', time: new Date().toLocaleString() }
          ]);
        }
      } catch (err) {
        console.error('Error loading admin data:', err);
        showCustomPopup(`Failed to load admin data: ${err.message}`, 'error');
      }
    };

    if (user?.isAdmin) {
      loadData();
    } else {
      showCustomPopup('Access Denied: Admin privileges required', 'error');
    }
  }, [user, delay, retryRequest]); // Dependencies array includes all functions used inside effect

  const handleAddPet = async (e) => {
    e.preventDefault();

    // 更精确的验证：检查值是否为null或空字符串，而不是仅依赖真值检查
    if (!newPet.name || !newPet.rarity || newPet.value === '') {
      showCustomPopup('Please fill in all required fields', 'error');
      return;
    }

    // 验证数值是否为有效数字且大于等于0
    const numericValue = parseFloat(newPet.value);
    if (isNaN(numericValue) || numericValue < 0) {
      showCustomPopup('Value must be a valid number greater than or equal to 0', 'error');
      return;
    }

    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/items`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          ...newPet,
          value: numericValue // 确保发送的是数字而不是字符串
        })
      }));

      if (response.ok) {
        const result = await response.json();
        setPets([...pets, result.pet]);
        setNewPet({ name: '', rarity: 'common', value: 0, imageUrl: '' });
        showCustomPopup('Pet added successfully!', 'success');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || `Failed to add pet: ${response.statusText}`, 'error');
      }
    } catch (err) {
      console.error('Error adding pet:', err);
      showCustomPopup(`Error adding pet: ${err.message}`, 'error');
    }
  };

  const handleRemovePet = async (petId) => {
    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/items/${petId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        }
      }));

      if (response.ok) {
        setPets(pets.filter(pet => pet.id !== petId));
        showCustomPopup('Pet removed successfully!', 'success');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || `Failed to remove pet: ${response.statusText}`, 'error');
      }
    } catch (err) {
      console.error('Error removing pet:', err);
      showCustomPopup(`Error removing pet: ${err.message}`, 'error');
    }
  };

  const handleUpdateBotSettings = async () => {
    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/settings`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify(botSettings)
      }));

      if (response.ok) {
        const data = await response.json();
        setBotSettings(data.settings || botSettings);
        showCustomPopup('Bot settings updated successfully!', 'success');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || 'Failed to update settings', 'error');
      }
    } catch (err) {
      console.error('Error updating settings:', err);
      showCustomPopup(`Error updating settings: ${err.message}`, 'error');
    }
  };

  const handleViewUserPets = async (usr) => {
    setSelectedUser(usr);
    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/inventory/${usr.id}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        }
      }));

      if (response.ok) {
        const data = await response.json();
        setUserPets(data.items || []);
      } else {
        const errorData = await response.json();
        console.error('Error fetching user pets:', errorData);
        setUserPets([]);
        showCustomPopup(errorData.message || `Failed to fetch user pets: ${response.statusText}`, 'error');
      }
    } catch (err) {
      console.error('Error fetching user pets:', err);
      setUserPets([]);
      showCustomPopup(`Error fetching user pets: ${err.message}`, 'error');
    }
  };

  const handleAddPetToUser = async () => {
    if (!selectedUser || !newPet.id) {
      showCustomPopup('Please select a user and a pet', 'error');
      return;
    }

    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/user/${selectedUser.id}/add-pet`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ petId: newPet.id })
      }));

      if (response.ok) {
        showCustomPopup(`Pet added to user ${selectedUser.displayName}`, 'success');
        // Refresh user's pets
        handleViewUserPets(selectedUser);
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || `Failed to add pet to user: ${response.statusText}`, 'error');
      }
    } catch (err) {
      console.error('Error adding pet to user:', err);
      showCustomPopup(`Error adding pet to user: ${err.message}`, 'error');
    }
  };

  const handleRemovePetFromUser = async (petId) => {
    if (!selectedUser) {
      showCustomPopup('No user selected', 'error');
      return;
    }

    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/user/${selectedUser.id}/remove-pet/${petId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        }
      }));

      if (response.ok) {
        setUserPets(userPets.filter(pet => pet.id !== petId));
        showCustomPopup('Pet removed from user successfully!', 'success');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || `Failed to remove pet from user: ${response.statusText}`, 'error');
      }
    } catch (err) {
      console.error('Error removing pet from user:', err);
      showCustomPopup(`Error removing pet from user: ${err.message}`, 'error');
    }
  };

  const handleApproveTransaction = async (transactionId) => {
    try {
      setTransactionsLoading(true);
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/withdrawals/${transactionId}/status`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: 'completed' })
      }));

      if (response.ok) {
        setPendingTransactions(pendingTransactions.filter(t => t.id !== transactionId));
        showCustomPopup('Transaction approved successfully!', 'success');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || 'Failed to approve transaction', 'error');
      }
    } catch (err) {
      console.error('Error approving transaction:', err);
      showCustomPopup(`Error approving transaction: ${err.message}`, 'error');
    } finally {
      setTransactionsLoading(false);
    }
  };

  const handleMarkAsPending = async (transactionId) => {
    try {
      setTransactionsLoading(true);
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/withdrawals/${transactionId}/status`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: 'pending' })
      }));

      if (response.ok) {
        // local state
        setPendingTransactions(pendingTransactions.map(t => 
          t.id === transactionId ? { ...t, status: 'pending' } : t
        ));
        showCustomPopup('Transaction marked as pending!', 'info');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || 'Failed to update transaction status', 'error');
      }
    } catch (err) {
      console.error('Error updating transaction status:', err);
      showCustomPopup(`Error updating transaction status: ${err.message}`, 'error');
    } finally {
      setTransactionsLoading(false);
    }
  };

  const handleRejectTransaction = async (transactionId) => {
    try {
      setTransactionsLoading(true);
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/withdrawals/${transactionId}/status`, {
        method: 'PUT',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ status: 'rejected' })
      }));

      if (response.ok) {
        setPendingTransactions(pendingTransactions.filter(t => t.id !== transactionId));
        showCustomPopup('Transaction rejected successfully!', 'success');
      } else {
        const errorData = await response.json();
        showCustomPopup(errorData.message || 'Failed to reject transaction', 'error');
      }
    } catch (err) {
      console.error('Error rejecting transaction:', err);
      showCustomPopup(`Error rejecting transaction: ${err.message}`, 'error');
    } finally {
      setTransactionsLoading(false);
    }
  };

  // Search users function
  const handleSearchUsers = async (term) => {
    try {
      const response = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/users?search=${encodeURIComponent(term)}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        }
      }));

      if (response.ok) {
        const data = await response.json();
        setUsers(data.users || []);
      } else {
        throw new Error(`Failed to search users: ${response.status}`);
      }
    } catch (err) {
      console.error('Error searching users:', err);
      showCustomPopup(`Error searching users: ${err.message}`, 'error');
    }
  };

  const handleClearSearch = () => {
    setSearchTerm('');
    setUsers(allUsers);
  };

  // Show loading state while checking admin status
  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading Admin Panel...</p>
      </div>
    );
  }

  // Show access denied if user is not admin
  if (!user?.isAdmin) {
    return (
      <div className="loading-container">
        <p>Access Denied: Admin privileges required</p>
      </div>
    );
  }

  return (
    <div className="admin-panel">
      <div className="page-header">
        <h1>Admin Panel</h1>
      </div>

      <div className="admin-content">
        <div className="admin-tabs">
          <button 
            className={`tab-btn ${activeTab === 'dashboard' ? 'active' : ''}`}
            onClick={() => setActiveTab('dashboard')}
          >
            Dashboard
          </button>
          <button 
            className={`tab-btn ${activeTab === 'users' ? 'active' : ''}`}
            onClick={() => setActiveTab('users')}
          >
            Manage Users
          </button>
          <button 
            className={`tab-btn ${activeTab === 'pets' ? 'active' : ''}`}
            onClick={() => setActiveTab('pets')}
          >
            Manage Pets
          </button>
          <button 
            className={`tab-btn ${activeTab === 'transactions' ? 'active' : ''}`}
            onClick={() => setActiveTab('transactions')}
          >
            Transactions
          </button>
          <button 
            className={`tab-btn ${activeTab === 'settings' ? 'active' : ''}`}
            onClick={() => setActiveTab('settings')}
          >
            Settings
          </button>
        </div>

        <div className="admin-tab-content">
          {activeTab === 'dashboard' && (
            <div className="admin-dashboard">
              <div className="admin-stats-grid">
                <div className="stat-card">
                  <h3>Total Users</h3>
                  <p className="stat-number">{allUsers.length}</p>
                </div>
                <div className="stat-card">
                  <h3>Total Pets</h3>
                  <p className="stat-number">{pets.length}</p>
                </div>
                <div className="stat-card">
                  <h3>Pending Transactions</h3>
                  <p className="stat-number">{pendingTransactions.length}</p>
                </div>
                <div className="stat-card">
                  <h3>Total Value in Circulation</h3>
                  <p className="stat-number">12,500 AMP</p>
                </div>
              </div>

              <div className="recent-activity">
                <h3>Recent Activity</h3>
                <div className="activity-list">
                  {recentActivity.length > 0 ? (
                    recentActivity.map((activity, index) => (
                      <div key={index} className="activity-item">
                        <span className="activity-type">{activity.type}</span>
                        <span className="activity-user">{activity.user}</span>
                        <span className="activity-time">{activity.time}</span>
                      </div>
                    ))
                  ) : (
                    <div className="no-activity">No recent activity</div>
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'users' && (
            <div className="manage-users">
              <div className="search-bar">
                <form onSubmit={handleSearchUsers}>
                  <input
                    type="text"
                    placeholder="Search users by username, display name, or ID..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="form-control"
                  />
                  <button type="submit" className="btn btn-primary">Search</button>
                  <button 
                    type="button" 
                    className="btn btn-secondary" 
                    onClick={handleClearSearch}
                  >
                    Clear
                  </button>
                </form>
              </div>

              <div className="users-table">
                <table className="table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Username</th>
                      <th>Display Name</th>
                      <th>Balance</th>
                      <th>Role</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.map(usr => (
                      <tr key={usr.id}>
                        <td>{usr.id}</td>
                        <td>{usr.robloxUsername}</td>
                        <td>{usr.displayName}</td>
                        <td>{usr.balance} AMP</td>
                        <td>{usr.isAdmin ? 'Admin' : 'User'}</td>
                        <td>
                          <button 
                            className="btn btn-secondary"
                            onClick={() => handleViewUserPets(usr)}
                          >
                            View Pets
                          </button>
                          <button className="btn btn-danger">Ban</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {selectedUser && (
                <div className="user-pets-section">
                  <h3>Pets for {selectedUser.displayName}</h3>
                  <div className="inventory-grid">
                    {userPets.map(item => (
                      <div key={item.id} className="inventory-item">
                        <div className="inventory-item-info">
                          <div className="item-name">{item.details?.name || item.name}</div>
                          <div className="item-value">{item.value} AMP</div>
                          <span className={`badge badge-${item.details?.rarity || item.rarity}`}>
                            {item.details?.rarity || item.rarity}
                          </span>
                        </div>
                        <button 
                          className="btn btn-danger"
                          onClick={() => handleRemovePetFromUser(item.id)}
                        >
                          Remove
                        </button>
                      </div>
                    ))}
                  </div>
                  <div className="add-pet-to-user">
                    <select 
                      className="form-control"
                      value={newPet.id || ''}
                      onChange={(e) => setNewPet({...newPet, id: parseInt(e.target.value)})}
                    >
                      <option value="">Select Pet to Add</option>
                      {pets.map(pet => (
                        <option key={pet.id} value={pet.id}>{pet.name} ({pet.value} AMP)</option>
                      ))}
                    </select>
                    <button 
                      className="btn btn-primary"
                      onClick={handleAddPetToUser}
                    >
                      Add Pet to User
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'pets' && (
            <div className="manage-pets">
              <div className="add-pet-form">
                <h3>Add New Pet</h3>
                <form onSubmit={handleAddPet}>
                  <div className="form-group">
                    <label className="form-label">Pet Name</label>
                    <input
                      type="text"
                      className="form-control"
                      value={newPet.name}
                      onChange={(e) => setNewPet({...newPet, name: e.target.value})}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Rarity</label>
                    <select
                      className="form-control"
                      value={newPet.rarity}
                      onChange={(e) => setNewPet({...newPet, rarity: e.target.value})}
                    >
                      <option value="common">Common</option>
                      <option value="uncommon">Uncommon</option>
                      <option value="rare">Rare</option>
                      <option value="epic">Epic</option>
                      <option value="legendary">Legendary</option>
                      <option value="mythic">Mythic</option>
                    </select>
                  </div>
                  <div className="form-group">
                    <label className="form-label">Value (AMP)</label>
                    <input
                      type="number"
                      className="form-control"
                      value={newPet.value}
                      onChange={(e) => setNewPet({...newPet, value: parseInt(e.target.value)})}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Image URL</label>
                    <input
                      type="text"
                      className="form-control"
                      value={newPet.imageUrl}
                      onChange={(e) => setNewPet({...newPet, imageUrl: e.target.value})}
                    />
                  </div>
                  <button type="submit" className="btn btn-primary">Add Pet</button>
                </form>
              </div>

              <div className="pets-list">
                <h3>All Pets</h3>
                <div className="inventory-grid">
                  {pets.map(pet => (
                    <div key={pet.id} className="inventory-item">
                      <div className="inventory-item-info">
                        <div className="item-name">{pet.name}</div>
                        <div className="item-value">{pet.value} AMP</div>
                        <span className={`badge badge-${pet.rarity}`}>
                          {pet.rarity}
                        </span>
                      </div>
                      <button 
                        className="btn btn-danger"
                        onClick={() => handleRemovePet(pet.id)}
                      >
                        Remove
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'transactions' && (
            <div className="manage-transactions">
              <div className="transactions-header">
                <h3>Pending Transactions</h3>
                <button 
                  className="btn btn-refresh"
                  onClick={async () => {
                    setTransactionsLoading(true);
                    try {
                      const transactionsResponse = await retryRequest(() => fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/transactions/pending`, {
                        headers: {
                          'Authorization': `Bearer ${localStorage.getItem('token')}`,
                          'Content-Type': 'application/json'
                        }
                      }));

                      if (transactionsResponse.ok) {
                        const transactionsData = await transactionsResponse.json();
                        setPendingTransactions(transactionsData.transactions || []);
                        setTransactionError(''); // Clear any previous error
                      } else {
                        throw new Error(`Failed to refresh transactions: ${transactionsResponse.status}`);
                      }
                    } catch (err) {
                      console.error('Error refreshing transactions:', err);
                      setTransactionError(`Failed to refresh transactions: ${err.message}`);
                      showCustomPopup(`Failed to refresh transactions: ${err.message}`, 'error');
                    } finally {
                      setTransactionsLoading(false);
                    }
                  }}
                  disabled={transactionsLoading}
                >
                  {transactionsLoading ? 'Refreshing...' : 'Refresh'}
                </button>
              </div>

              {transactionError && (
                <div className="alert alert-danger">{transactionError}</div>
              )}

              <div className="transactions-table">
                <table className="table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>User</th>
                      <th>Amount</th>
                      <th>Type</th>
                      <th>Status</th>
                      <th>Date</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pendingTransactions.length > 0 ? (
                      pendingTransactions.map(transaction => (
                        <tr key={transaction.id}>
                          <td>{transaction.id}</td>
                          <td>{transaction.userId}</td>
                          <td>{transaction.amount} AMP</td>
                          <td>{transaction.type}</td>
                          <td>
                            <span className={`badge ${
                              transaction.status === 'completed' ? 'badge-success' :
                              transaction.status === 'pending' ? 'badge-warning' :
                              'badge-danger'
                            }`}>
                              {transaction.status}
                            </span>
                          </td>
                          <td>{new Date(transaction.timestamp).toLocaleString()}</td>
                          <td>
                            <button 
                              className="btn btn-success"
                              onClick={() => handleApproveTransaction(transaction.id)}
                            >
                              Approve
                            </button>
                            <button 
                              className="btn btn-warning"
                              onClick={() => handleMarkAsPending(transaction.id)}
                            >
                              Pending
                            </button>
                            <button 
                              className="btn btn-danger"
                              onClick={() => handleRejectTransaction(transaction.id)}
                            >
                              Reject
                            </button>
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan="7">No pending transactions</td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="admin-settings">
              <div className="bot-settings">
                <h3>Bot Settings</h3>
                <div className="form-group">
                  <label className="form-label">Bot Username</label>
                  <input
                    type="text"
                    className="form-control"
                    value={botSettings.botUser}
                    onChange={(e) => setBotSettings({...botSettings, botUser: e.target.value})}
                    placeholder="Enter bot username"
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Redirect Link</label>
                  <input
                    type="text"
                    className="form-control"
                    value={botSettings.redirectLink}
                    onChange={(e) => setBotSettings({...botSettings, redirectLink: e.target.value})}
                    placeholder="Enter redirect link"
                  />
                </div>
                <button 
                  className="btn btn-primary"
                  onClick={handleUpdateBotSettings}
                >
                  Save Settings
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
      <AnimatedPopup 
        show={showPopup} 
        onClose={closePopup} 
        message={popupMessage} 
        type={popupType} 
      />
    </div>
  );
};

export default AdminPanel;
